<?php
if(Access::role()==='ALUMNO'){redirect('inicio');}
$archived=manage()&&($_GET['archivados']??'')==='1';
[$scope,$scopeParams]=Access::equipmentScope($archived);
$search=is_string($_GET['q']??null)?substr(trim($_GET['q']),0,255):'';
$labFilter=is_string($_GET['lab']??null)&&ctype_digit($_GET['lab'])?$_GET['lab']:'';
$stateFilter=is_string($_GET['estado']??null)&&isset(Inventory::STATES[$_GET['estado']])?$_GET['estado']:'';
$number=max(1,min(100000,(int)($_GET['n']??1))); $offset=($number-1)*25;
$where=[$scope];$params=$scopeParams;
if($search!==''){$where[]='(e.hostname LIKE ? OR e.num_serie LIKE ? OR e.smbios_uuid LIKE ?)';$params=[...$params,"%$search%","%$search%","%$search%"];}if($labFilter!==''){$where[]='e.id_laboratorio=?';$params[]=$labFilter;}if($stateFilter!==''){$where[]='e.estado_administrativo=?';$params[]=$stateFilter;}
$clause=$where?' WHERE '.implode(' AND ',$where):'';
$total=(int)query('SELECT COUNT(*) FROM equipo e'.$clause,$params)->fetchColumn();
$pcs=query('SELECT e.*,l.nombre laboratorio FROM equipo e LEFT JOIN laboratorio l ON l.id_laboratorio=e.id_laboratorio'.$clause.' ORDER BY e.id_equipo DESC LIMIT 25 OFFSET '.$offset,$params)->fetchAll();
[$labScope,$labParams]=Access::labScope();
$labs=query('SELECT l.* FROM laboratorio l WHERE '.$labScope.' ORDER BY l.nombre',$labParams)->fetchAll();
$edit=null;$id=is_string($_GET['edit']??null)?$_GET['edit']:'';
if(manage()&&ctype_digit($id)){$edit=Access::equipment($id);}
$value=fn($key,$default='')=>input('action')==='save_equipment'?input($key):($edit[$key]??$default);
?>
<div class="page-heading"><div><p class="eyebrow">INVENTARIO</p><h1>Equipos</h1><p class="muted"><?= manage()?'Identificá cada PC y asignala a su laboratorio.':'Solo se muestran las PC de tu laboratorio actual.' ?></p></div><?php if(manage()): ?><div><a class="text-link" href="<?= e(url('equipos',['archivados'=>$archived?'0':'1'])) ?>"><?= $archived?'Ver activos':'Ver eliminados' ?></a> <a class="button" href="#formulario">+ Registrar PC</a></div><?php endif ?></div>
<section class="panel"><form class="filters" method="get" action="/"><input type="hidden" name="page" value="equipos"><input type="hidden" name="archivados" value="<?= $archived?'1':'0' ?>"><div class="search-field"><label for="q">Buscar equipo</label><input id="q" name="q" placeholder="Nombre, serie o UUID" value="<?= e($search) ?>"></div><div><label for="lab">Laboratorio</label><select id="lab" name="lab"><option value="">Todos los laboratorios</option><?php foreach($labs as $lab): ?><option value="<?= e($lab['id_laboratorio']) ?>" <?= $labFilter===$lab['id_laboratorio']?'selected':((string)$lab['id_laboratorio']===$labFilter?'selected':'') ?>><?= e($lab['nombre']) ?></option><?php endforeach ?></select></div><div><label for="estado">Estado administrativo</label><select id="estado" name="estado"><option value="">Todos los estados</option><?php foreach(Inventory::STATES as $key=>$label): ?><option value="<?= e($key) ?>" <?= $stateFilter===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></div><button class="button secondary" type="submit">Filtrar</button><a class="text-link" href="<?= e(url('equipos')) ?>">Limpiar</a></form>
<div class="panel-heading compact"><h2>Inventario de PC</h2><span class="count-label"><?= e($total) ?> equipos</span></div>
<?php if(!$pcs): ?><div class="empty"><h3>No hay equipos para mostrar</h3><p><?= $total===0&&$search===''&&$labFilter===''&&$stateFilter===''?'Registrá la primera PC con su serie o UUID SMBIOS.':'Probá otros filtros o registrá una PC.' ?></p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Equipo / identificación</th><th>Laboratorio</th><th>Estado administrativo</th><th>Acciones</th></tr></thead><tbody><?php foreach($pcs as $pc): ?><tr><td><a class="table-link" href="<?= e(url('equipo',['id'=>$pc['id_equipo']])) ?>"><?= e($pc['hostname']?:'PC #'.$pc['id_equipo']) ?></a><small class="cell-sub mono"><?= e($pc['num_serie']?:$pc['smbios_uuid']) ?></small></td><td><?= e($pc['laboratorio']??'Sin asignar') ?></td><td><span class="badge <?= $pc['estado_administrativo']==='OPERATIVA'?'good':'warn' ?>"><?= e(Inventory::STATES[$pc['estado_administrativo']]) ?></span></td><td class="actions"><?php if(!$archived): ?><a href="<?= e(url('equipo',['id'=>$pc['id_equipo']])) ?>">Detalle</a><?php endif ?><?php if(manage()): ?><?php if(!$archived): ?><a href="<?= e(url('equipos',['edit'=>$pc['id_equipo']])) ?>#formulario">Editar</a><?php endif ?><form class="inline-form" method="post" action="<?= e(url('equipos')) ?>"><?= csrf() ?><input type="hidden" name="action" value="archive_equipment"><input type="hidden" name="id" value="<?= e($pc['id_equipo']) ?>"><input type="hidden" name="restore" value="<?= $archived?'1':'0' ?>"><button class="link-button" type="submit"><?= $archived?'Restaurar':'Eliminar (archivar)' ?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<div class="pagination"><span>Página <?= e($number) ?> · 25 equipos por página</span><div><?php if($number>1): ?><a href="<?= e(url('equipos',['q'=>$search,'lab'=>$labFilter,'estado'=>$stateFilter,'n'=>$number-1,'archivados'=>$archived?'1':'0'])) ?>">← Anterior</a><?php endif ?><?php if($offset+25<$total): ?><a href="<?= e(url('equipos',['q'=>$search,'lab'=>$labFilter,'estado'=>$stateFilter,'n'=>$number+1,'archivados'=>$archived?'1':'0'])) ?>">Siguiente →</a><?php endif ?></div></div></section>
<?php if(manage()): ?><section class="panel form-panel equipment-form" id="formulario"><p class="eyebrow">ADMINISTRACIÓN</p><h2><?= $edit?'Editar PC':'Registrar una PC' ?></h2><p class="muted">Copiá la serie o el UUID de la captura TOML. El servidor los usa para reconocer el equipo.</p>
<?php if(!$labs): ?><div class="alert">Primero <a href="<?= e(url('laboratorios')) ?>">creá un laboratorio</a> para asignar la PC.</div><?php else: ?><form method="post" action="<?= e(url('equipos',$edit?['edit'=>$edit['id_equipo']]:[])) ?>"><?= csrf() ?><input type="hidden" name="action" value="save_equipment"><input type="hidden" name="id" value="<?= e($edit['id_equipo']??'') ?>"><div class="form-grid">
<div><label for="hostname">Nombre de la PC <span class="optional">opcional</span></label><input id="hostname" name="hostname" maxlength="255" placeholder="Ej. LAB6-PC01" value="<?= e($value('hostname')) ?>"></div>
<div><label for="id_laboratorio">Laboratorio</label><select id="id_laboratorio" name="id_laboratorio" required><option value="">Seleccionar laboratorio</option><?php foreach($labs as $lab): ?><option value="<?= e($lab['id_laboratorio']) ?>" <?= (string)$value('id_laboratorio')===(string)$lab['id_laboratorio']?'selected':'' ?>><?= e($lab['nombre']) ?></option><?php endforeach ?></select></div>
<div><label for="num_serie">Número de serie</label><input id="num_serie" name="num_serie" maxlength="100" value="<?= e($value('num_serie')) ?>"><small>Obligatorio si no indicás UUID SMBIOS.</small></div>
<div><label for="smbios_uuid">UUID SMBIOS</label><input id="smbios_uuid" name="smbios_uuid" maxlength="36" placeholder="XXXXXXXX-XXXX-XXXX-XXXX-XXXXXXXXXXXX" value="<?= e($value('smbios_uuid')) ?>"><small>Obligatorio si no indicás número de serie.</small></div>
<div><label for="estado_administrativo">Estado administrativo</label><select id="estado_administrativo" name="estado_administrativo"><?php foreach(Inventory::STATES as $key=>$label): ?><option value="<?= e($key) ?>" <?= $value('estado_administrativo','OPERATIVA')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></div></div>
<div class="form-actions"><button class="button" type="submit"><?= $edit?'Guardar cambios':'Registrar PC' ?></button><?php if($edit): ?><a class="cancel" href="<?= e(url('equipos')) ?>">Cancelar edición</a><?php endif ?></div></form><?php endif ?></section><?php endif ?>

<?php if(manage()): ?><section class="panel form-panel" id="importar-pc"><h2>Importar PC desde CSV</h2>
<p>Seleccioná el laboratorio de destino para todas las PC del archivo. Solo se crean equipos nuevos: no se modifican ni se restauran equipos existentes. Si una fila falla, no se importa ninguna PC.</p>
<p>Archivo UTF-8, hasta 1 MiB y 500 PC, separado por coma o punto y coma. Encabezado obligatorio:</p>
<pre>hostname,num_serie,smbios_uuid,estado_administrativo</pre>
<p>Indicá al menos una serie real o un UUID SMBIOS por PC. El nombre es opcional; el estado vacío se interpreta como OPERATIVA. También se admiten EN_REPARACION y FUERA_DE_SERVICIO.</p>
<p><a href="/assets/ejemplo-pc.csv" download>Descargar CSV de ejemplo</a>. Reemplazá los datos de ejemplo por las identidades reales del TOML.</p>
<?php if(!$labs): ?><p>Primero creá un laboratorio para poder importar PC.</p><?php else: ?>
<form method="post" enctype="multipart/form-data" action="<?= e(url('equipos')) ?>"><?= csrf() ?><input type="hidden" name="action" value="import_equipment">
<label for="laboratorio_csv">Laboratorio de destino</label><select id="laboratorio_csv" name="laboratorio_csv" required><option value="">Seleccionar laboratorio</option>
<?php foreach($labs as $lab): ?><option value="<?= e($lab['id_laboratorio']) ?>" <?= input('action')==='import_equipment'&&input('laboratorio_csv')===(string)$lab['id_laboratorio']?'selected':'' ?>><?= e($lab['nombre']) ?></option><?php endforeach ?></select>
<label for="equipment_csv">Archivo CSV de PC</label><input id="equipment_csv" name="csv" type="file" accept=".csv,text/csv" required>
<button class="button" type="submit">Importar PC</button></form><?php endif ?></section><?php endif ?>
